/*
 * TEST DOUBLES ONLY. Nothing here calls an AI model, an embedding model or a vector database.
 * Outputs are fixed strings and fixed numbers chosen by the tests, and the AI provider marks
 * itself as a test double so the orchestrator stores its text with isTestData=true.
 */
import type {
  EmbeddingModelConfig,
  EmbeddingProvider,
  VectorMatch,
  VectorRecord,
  VectorStore,
} from '../../src/modules/knowledge/embeddings/embedding.interfaces';
import {
  AiProviderError,
  type AiGenerationInput,
  type AiGenerationResult,
  type AiProvider,
} from '../../src/modules/ai/orchestration/ai.interfaces';

export const TEST_AI_PROVIDER_ID = 'test-double';
export const TEST_EMBEDDING_PROVIDER_ID = 'test-embeddings';

export const TEST_FIXTURE_RESPONSE =
  '[TEST FIXTURE] Fixed test output, not generated by an AI model. Water at the base of the stem [1].';

type Behaviour = { kind: 'respond'; result: AiGenerationResult } | { kind: 'throw'; error: Error };

export class TestDoubleAiProvider implements AiProvider {
  readonly id = TEST_AI_PROVIDER_ID;
  readonly isTestDouble = true;
  readonly calls: AiGenerationInput[] = [];
  private queue: Behaviour[] = [];

  /** Scripted results for the next calls; when empty, the default fixture is returned. */
  respondWith(result: AiGenerationResult): this {
    this.queue.push({ kind: 'respond', result });
    return this;
  }

  failWith(message: string, retryable: boolean): this {
    this.queue.push({ kind: 'throw', error: new AiProviderError(message, retryable) });
    return this;
  }

  reset(): void {
    this.calls.length = 0;
    this.queue = [];
  }

  async generate(input: AiGenerationInput): Promise<AiGenerationResult> {
    this.calls.push(input);
    const next = this.queue.shift();
    if (next?.kind === 'throw') throw next.error;
    if (next?.kind === 'respond') return next.result;
    return {
      content: TEST_FIXTURE_RESPONSE,
      usage: { inputTokens: 11, outputTokens: 7, totalTokens: 18 },
    };
  }
}

/** Returns the same vector for every text; similarity comes from TestVectorStore. */
export class TestEmbeddingProvider implements EmbeddingProvider {
  readonly id = TEST_EMBEDDING_PROVIDER_ID;

  async embed(texts: string[], config: EmbeddingModelConfig): Promise<number[][]> {
    return texts.map(() => new Array<number>(config.dimensions).fill(0));
  }
}

/** Returns whatever candidates the test configured, in order. */
export class TestVectorStore implements VectorStore {
  readonly id = 'test-vector-store';
  candidates: VectorMatch[] = [];

  async upsert(records: VectorRecord[]): Promise<string[]> {
    return records.map((record) => record.chunkId);
  }

  async query(_configurationId: string, _vector: number[], limit: number): Promise<VectorMatch[]> {
    return this.candidates.slice(0, limit);
  }

  async remove(): Promise<void> {}
}
